wp:postmeta.wp:meta_value:
[{"id":"d1a0c01","elType":"container","settings":{"content_width":"full","flex_gap":{"unit":"px","size":0,"column":"0","row":"0"},"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"_css_classes":"ciclo-page ciclo-dental-page"},"elements":[{"id":"d1a0c02","elType":"widget","widgetType":"html","settings":{"html":"<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.css">
<style>

 #ciclo-dental{
 --dark:#0d1030;
 --dark2:#141838;
 --navy:#1e2f8f; /* index 톤 승계: 진한 네이비 */
 --navy2:#1a2a80;
 --navy-deep:#16256e;
 --mint:#ffd400;
 --sky:#8fb8ff;
 --yellow:#ffd400; /* 브랜드 옐로우 */
 --yellow-s:#ffe14d;
 --white:#ffffff;
 --paper:#f7f5f0;
 --ink:#14141a;
 --sub:#5c5a54;
 --gray:#9c988f;
 --line:#e6e3dc;
 --red:#e8453c;
 --W:860px;
 --P:64px;
 }
 #ciclo-dental,#ciclo-dental *{margin:0;padding:0;box-sizing:border-box;}
 #ciclo-dental{
 font-family:'Pretendard','Pretendard Variable',-apple-system,'Malgun Gothic',sans-serif;
 background:#fff;color:var(--ink);
 -webkit-font-smoothing:antialiased;word-break:keep-all;
 }
 #ciclo-dental .page{width:var(--W);margin:0 auto;overflow:hidden;}

 #ciclo-dental /* ══════ 화면 단위 블록 ══════ */
 .scr{padding:120px var(--P);text-align:center;}
 #ciclo-dental .scr.lft{text-align:left;}
 #ciclo-dental .scr.sm{padding:88px var(--P);}

 #ciclo-dental /* 핵심 장면 = 한 스크롤에 하나씩 (스냅) */
 html{scroll-snap-type:y proximity;scroll-behavior:smooth;}
 #ciclo-dental .scr.snap{
 min-height:100vh;
 display:flex;flex-direction:column;justify-content:center;
 scroll-snap-align:center;scroll-snap-stop:always;
 padding-top:80px;padding-bottom:80px;
 }
 #ciclo-dental .scr.snap.lft{align-items:flex-start;}
 #ciclo-dental .b-dark{background:var(--dark);color:#fff;}
 #ciclo-dental .b-dark2{background:var(--dark2);color:#fff;}
 #ciclo-dental .b-navy{background:var(--navy);color:#fff;}
 #ciclo-dental .b-paper{background:var(--paper);}
 #ciclo-dental .b-white{background:#fff;}

 #ciclo-dental /* ══════ 타이포: 와디즈 스케일 ══════ */
 .xxl{font-size:88px;line-height:1.14;font-weight:800;letter-spacing:-.05em;}
 #ciclo-dental .xl{font-size:66px;line-height:1.22;font-weight:800;letter-spacing:-.045em;}
 #ciclo-dental .lg{font-size:48px;line-height:1.32;font-weight:800;letter-spacing:-.038em;}
 #ciclo-dental .md{font-size:32px;line-height:1.5;font-weight:700;letter-spacing:-.028em;}
 #ciclo-dental .bd{font-size:19px;line-height:1.9;font-weight:500;}
 #ciclo-dental .cap{font-size:14px;line-height:1.75;font-weight:500;}

 #ciclo-dental .b-dark .bd,#ciclo-dental .b-dark2 .bd,#ciclo-dental .b-navy .bd{color:rgba(255,255,255,.72);}
 #ciclo-dental .b-paper .bd,#ciclo-dental .b-white .bd{color:var(--sub);}
 #ciclo-dental .b-dark .cap,#ciclo-dental .b-dark2 .cap,#ciclo-dental .b-navy .cap{color:rgba(255,255,255,.42);}
 #ciclo-dental .b-paper .cap,#ciclo-dental .b-white .cap{color:var(--gray);}

 #ciclo-dental .mt-s{margin-top:20px;} #ciclo-dental .mt-m{margin-top:34px;} #ciclo-dental .mt-l{margin-top:54px;}
 #ciclo-dental .center-bd{max-width:620px;margin-left:auto;margin-right:auto;}

 #ciclo-dental /* ══════ 강조 장치 ══════ */
 .box{
 display:inline-block;padding:4px 16px;border-radius:8px;
 background:var(--navy);color:#fff;
 }
 #ciclo-dental .box.w{background:#fff;color:var(--navy);}
 #ciclo-dental .box.mint{background:var(--mint);color:var(--dark);}
 #ciclo-dental .box.yel{background:var(--yellow);color:var(--navy);}
 #ciclo-dental .box.red{background:var(--red);color:#fff;}
 #ciclo-dental .box.grad{background:linear-gradient(90deg,var(--yellow),var(--yellow-s));color:var(--navy);}
 #ciclo-dental .mint-t{color:var(--mint);}
 #ciclo-dental .sky-t{color:var(--sky);}
 #ciclo-dental .yel-t{color:var(--yellow);}
 #ciclo-dental .navy-t{color:var(--navy);}
 #ciclo-dental .hand{
 font-family:'Gaegu',cursive;font-weight:700;
 color:var(--navy);letter-spacing:0;
 line-height:1.5;display:inline-block;padding-bottom:.12em;
 }
 #ciclo-dental .b-dark .hand,#ciclo-dental .b-dark2 .hand,#ciclo-dental .b-navy .hand{color:#fff;}
 #ciclo-dental /* 어두운 배경 위 형광펜은 글자를 네이비로 반전 */
 .b-dark .hand.pen.on,#ciclo-dental .b-dark2 .hand.pen.on,#ciclo-dental .b-navy .hand.pen.on{color:var(--navy);}
 #ciclo-dental .uline{
 background:linear-gradient(transparent 62%,var(--yellow) 62%);
 padding:0 4px;
 }
 #ciclo-dental .chev{margin:40px auto;width:36px;opacity:.55;}
 #ciclo-dental .chev svg{width:100%;}

 #ciclo-dental /* ══════ 상단 요약 ══════ */
 .top{padding:32px var(--P) 36px;border-bottom:1px solid var(--line);}
 #ciclo-dental .top .id{display:flex;align-items:center;gap:11px;margin-bottom:24px;}
 #ciclo-dental .top .id .m{width:30px;height:30px;border-radius:7px;background:var(--navy2);
 display:flex;align-items:center;justify-content:center;}
 #ciclo-dental .top .id .m svg{width:19px;height:19px;}
 #ciclo-dental .top .id .n{font-size:14px;font-weight:800;letter-spacing:.16em;color:var(--navy2);}
 #ciclo-dental .top .id .g{font-size:11px;font-weight:800;color:#1aa06d;background:rgba(26,160,109,.1);
 padding:4px 10px;border-radius:4px;}
 #ciclo-dental .top h1{font-size:29px;font-weight:800;letter-spacing:-.035em;line-height:1.42;margin-bottom:9px;}
 #ciclo-dental .top .s{font-size:15.5px;color:var(--sub);margin-bottom:28px;}
 #ciclo-dental .gg{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:11px;}
 #ciclo-dental .gg .p{font-size:32px;font-weight:800;letter-spacing:-.04em;color:var(--navy2);}
 #ciclo-dental .gg .p small{font-size:16px;font-weight:700;margin-left:3px;}
 #ciclo-dental .gg .r{font-size:13.5px;font-weight:800;color:var(--red);}
 #ciclo-dental .tk{height:7px;background:var(--line);border-radius:100px;overflow:hidden;}
 #ciclo-dental .tk i{display:block;height:100%;width:70%;background:var(--navy2);border-radius:100px;}
 #ciclo-dental .mt2{display:flex;gap:24px;font-size:13.5px;color:var(--sub);margin-top:13px;}
 #ciclo-dental .mt2 b{color:var(--ink);font-weight:800;}

 #ciclo-dental /* ══════ 견적서 그래픽 ══════ */
 .quote{
 margin:44px auto 0;max-width:520px;background:#fff;border-radius:12px;
 padding:28px 30px;text-align:left;box-shadow:0 18px 50px rgba(0,0,0,.4);
 transform:rotate(-1.4deg);
 }
 #ciclo-dental .quote .qh{
 font-size:12px;font-weight:800;letter-spacing:.16em;color:#9c988f;
 padding-bottom:14px;border-bottom:2px solid var(--ink);margin-bottom:6px;
 }
 #ciclo-dental .quote .qr{
 display:flex;justify-content:space-between;gap:16px;padding:11px 0;
 border-bottom:1px solid var(--line);font-size:15px;color:#4c4a44;text-align:left;
 }
 #ciclo-dental .quote .qr b{font-weight:700;color:var(--ink);white-space:nowrap;}
 #ciclo-dental .quote .qt{
 display:flex;justify-content:space-between;align-items:baseline;
 padding-top:16px;margin-top:6px;
 }
 #ciclo-dental .quote .qt .l{font-size:14px;font-weight:800;color:var(--gray);letter-spacing:.06em;}
 #ciclo-dental .quote .qt .v{font-size:34px;font-weight:800;letter-spacing:-.04em;color:var(--ink);}
 #ciclo-dental .quote .qt .v small{font-size:17px;}

 #ciclo-dental /* ══════ 검색결과 ══════ */
 .serp{
 margin:32px auto 0;max-width:520px;background:#fff;border-radius:10px;overflow:hidden;
 text-align:left;box-shadow:0 18px 50px rgba(0,0,0,.34);
 max-height:58vh;overflow-y:auto;
 scrollbar-width:thin;scrollbar-color:#d8d4cc transparent;
 }
 #ciclo-dental .serp::-webkit-scrollbar{width:5px;}
 #ciclo-dental .serp::-webkit-scrollbar-thumb{background:#d8d4cc;border-radius:3px;}
 #ciclo-dental .serp::-webkit-scrollbar-track{background:transparent;}
 #ciclo-dental .serp .sb{padding:13px 16px;border-bottom:1px solid var(--line);display:flex;gap:10px;
 align-items:center;justify-content:flex-start;background:#fbfaf8;}
 #ciclo-dental .serp .sb svg{width:15px;height:15px;opacity:.4;flex:0 0 15px;}
 #ciclo-dental .serp .sb span{font-size:14px;font-weight:700;color:#44423d;text-align:left;}
 #ciclo-dental .serp .rw{
 padding:7px 16px;border-bottom:1px solid #f4f2ee;
 display:flex;gap:9px;align-items:center;justify-content:flex-start;text-align:left;
 }
 #ciclo-dental .serp .rw .t{font-size:9px;font-weight:800;padding:2px 6px;border-radius:2px;flex:0 0 auto;
 background:#f0eeea;color:#928d82;text-align:center;letter-spacing:-.02em;}
 #ciclo-dental .serp .rw .t.ad{background:rgba(232,69,60,.11);color:#d63030;}
 #ciclo-dental .serp .rw .bl{flex:1;display:flex;flex-direction:column;gap:1px;min-width:0;}
 #ciclo-dental .serp .rw .bl b{
 font-size:12.5px;font-weight:600;color:#4a72c8;letter-spacing:-.025em;line-height:1.35;
 white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
 }
 #ciclo-dental .serp .rw .bl em{
 font-style:normal;font-size:10.5px;color:#a8a49b;letter-spacing:-.02em;line-height:1.35;
 white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
 }
 #ciclo-dental .serp .rw.me{
 background:var(--yellow);padding:13px 16px;
 border-top:2px solid #d9b400;border-bottom:none;
 }
 #ciclo-dental .serp .rw.me .t{background:rgba(0,0,0,.16);color:#5c4e00;}
 #ciclo-dental .serp .rw.me .bl{gap:3px;}
 #ciclo-dental .serp .rw.me .bl b.hot{color:var(--ink);font-weight:800;font-size:15px;}
 #ciclo-dental .serp .rw.me .bl em{color:#6b5a00;font-weight:700;font-size:12px;}
 #ciclo-dental .serp .dots{padding:9px 16px;text-align:center;font-size:13px;color:#c4c0b7;letter-spacing:.42em;}
 #ciclo-dental .serp .skip{
 display:flex;align-items:center;gap:14px;padding:22px 18px;background:#faf8f5;
 border-top:1px solid #eeece7;border-bottom:1px solid #eeece7;
 }
 #ciclo-dental .serp .skip .sl{flex:1;height:1px;background:#ddd9d1;}
 #ciclo-dental .serp .skip .sn{
 font-size:12.5px;font-weight:700;color:#948f85;white-space:nowrap;letter-spacing:-.02em;
 }
 #ciclo-dental .serp .skip .sn b{color:#d63030;font-weight:800;}
 #ciclo-dental .serp .scroll-note{
 padding:8px 16px;text-align:center;font-size:11px;font-weight:700;
 color:#b0aca3;background:#fbfaf8;border-bottom:1px solid #f4f2ee;letter-spacing:-.01em;
 }

 #ciclo-dental /* ══════ 두 갈래 카드 ══════ */
 .duo{display:flex;gap:16px;margin-top:52px;}
 #ciclo-dental .duo .d{
 flex:1;border-radius:16px;padding:34px 26px;text-align:center;
 border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.05);
 }
 #ciclo-dental .duo .d .dot{
 width:38px;height:38px;border-radius:50%;background:#fff;margin:0 auto 20px;
 display:flex;align-items:center;justify-content:center;
 }
 #ciclo-dental .duo .d .dot svg{width:19px;height:19px;}
 #ciclo-dental .duo .d .k{font-size:15px;font-weight:600;color:rgba(255,255,255,.66);margin-bottom:11px;}
 #ciclo-dental .duo .d .v{font-size:31px;font-weight:800;letter-spacing:-.035em;line-height:1.28;color:var(--mint);}

 #ciclo-dental /* ══════ 점수 비교판 ══════ */
 .score{margin-top:44px;text-align:left;}
 #ciclo-dental .score .shd{
 display:grid;grid-template-columns:1fr 96px 96px;gap:0;
 padding:0 18px 13px;border-bottom:2px solid rgba(255,255,255,.28);
 }
 #ciclo-dental .score .shd .c{
 font-size:12px;font-weight:800;letter-spacing:.04em;text-align:center;
 color:rgba(255,255,255,.5);
 }
 #ciclo-dental .score .shd .c.us{color:var(--yellow);}
 #ciclo-dental .score .shd .l{font-size:12px;font-weight:800;letter-spacing:.1em;color:rgba(255,255,255,.4);}

 #ciclo-dental .score .srow{
 display:grid;grid-template-columns:1fr 96px 96px;gap:0;align-items:center;
 padding:16px 18px;border-bottom:1px solid rgba(255,255,255,.11);
 }
 #ciclo-dental .score .srow .item b{
 display:block;font-size:16px;font-weight:700;letter-spacing:-.02em;margin-bottom:5px;color:#fff;
 }
 #ciclo-dental .score .srow .item span{
 font-size:13.5px;line-height:1.6;color:rgba(255,255,255,.52);
 }
 #ciclo-dental .score .mk{
 text-align:center;font-size:19px;font-weight:800;
 }
 #ciclo-dental .score .mk.no{color:#e8453c;}
 #ciclo-dental .score .mk.mid{color:#e8b23c;}
 #ciclo-dental .score .mk.yes{color:var(--yellow);}
 #ciclo-dental .score .mk small{display:block;font-size:10.5px;font-weight:700;margin-top:3px;opacity:.72;}

 #ciclo-dental .score .stot{
 display:grid;grid-template-columns:1fr 96px 96px;gap:0;align-items:center;
 padding:22px 18px;border-top:2px solid rgba(255,255,255,.28);margin-top:2px;
 }
 #ciclo-dental .score .stot .tl{font-size:15px;font-weight:800;color:rgba(255,255,255,.72);letter-spacing:.04em;}
 #ciclo-dental .score .stot .tv{text-align:center;font-size:34px;font-weight:800;letter-spacing:-.04em;line-height:1;}
 #ciclo-dental .score .stot .tv.bad{color:#e8453c;}
 #ciclo-dental .score .stot .tv.good{color:var(--yellow);}
 #ciclo-dental .score .stot .tv small{font-size:14px;font-weight:700;opacity:.6;}

 #ciclo-dental /* ══════ 위험 카드 ══════ */
 .risk{margin-top:46px;display:flex;flex-direction:column;gap:11px;text-align:left;}
 #ciclo-dental .risk .rk{
 background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);
 border-left:3px solid var(--red);border-radius:0 10px 10px 0;padding:20px 24px;
 }
 #ciclo-dental .risk .rh{
 font-size:13px;font-weight:800;color:var(--red);letter-spacing:.06em;margin-bottom:9px;
 }
 #ciclo-dental .risk .rk p{font-size:16px;line-height:1.8;color:rgba(255,255,255,.76);}

 #ciclo-dental /* ══════ 비교 ══════ */
 .vs{margin-top:48px;border-radius:14px;overflow:hidden;text-align:left;}
 #ciclo-dental .vs table{width:100%;border-collapse:collapse;background:#fff;}
 #ciclo-dental .vs th,#ciclo-dental .vs td{padding:18px 16px;text-align:left;font-size:15.5px;border-bottom:1px solid var(--line);}
 #ciclo-dental .vs thead th{font-size:13px;font-weight:800;padding:15px 16px;}
 #ciclo-dental .vs thead th.x{background:#f0eeea;color:#7d7970;}
 #ciclo-dental .vs thead th.o{background:var(--navy);color:#fff;}
 #ciclo-dental .vs tbody th{width:22%;font-weight:700;color:var(--gray);font-size:14px;background:#fbfaf8;}
 #ciclo-dental .vs td.x{width:39%;color:#8b877e;}
 #ciclo-dental .vs td.o{width:39%;color:var(--navy);font-weight:700;background:rgba(42,59,212,.05);}
 #ciclo-dental .vs tr:last-child th,#ciclo-dental .vs tr:last-child td{border-bottom:none;}
 #ciclo-dental .sg{font-weight:800;margin-right:6px;}
 #ciclo-dental .sg.x{color:#d63030;}#ciclo-dental .sg.o{color:var(--navy);}

 #ciclo-dental /* ══════ AI 답변 ══════ */
 .ai{
 margin:48px auto 0;max-width:600px;border-radius:14px;overflow:hidden;text-align:left;
 border:1px solid rgba(255,255,255,.2);
 }
 #ciclo-dental .ai .q{padding:18px 20px;background:rgba(255,255,255,.09);display:flex;gap:12px;align-items:center;
 justify-content:flex-start;border-bottom:1px solid rgba(255,255,255,.16);}
 #ciclo-dental .ai .q svg{width:16px;height:16px;opacity:.55;flex:0 0 16px;}
 #ciclo-dental .ai .q span{font-size:16px;font-weight:600;color:#fff;text-align:left;}
 #ciclo-dental .ai .a{padding:22px 20px;font-size:16px;line-height:1.9;color:rgba(255,255,255,.85);text-align:left;}
 #ciclo-dental .ai .a mark{background:rgba(94,234,212,.22);color:var(--mint);font-weight:700;padding:1px 5px;border-radius:3px;}
 #ciclo-dental .ai .c{padding:14px 20px;border-top:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.05);
 display:flex;gap:10px;align-items:center;}
 #ciclo-dental .ai .c .l{font-size:11px;font-weight:800;color:rgba(255,255,255,.4);letter-spacing:.08em;}
 #ciclo-dental .ai .c .s{font-size:12.5px;font-weight:700;color:var(--mint);border:1px solid rgba(94,234,212,.4);
 padding:4px 11px;border-radius:100px;}

 #ciclo-dental /* ══════ 스펙 행 ══════ */
 .rows{margin-top:44px;text-align:left;}
 #ciclo-dental .rows .r{display:flex;gap:22px;padding:21px 0;align-items:flex-start;
 border-bottom:1px solid rgba(255,255,255,.15);}
 #ciclo-dental .rows .r:first-child{border-top:1px solid rgba(255,255,255,.15);}
 #ciclo-dental .b-paper .rows .r,#ciclo-dental .b-white .rows .r{border-color:var(--line);}
 #ciclo-dental .rows .k{flex:0 0 100px;font-size:14.5px;font-weight:800;padding-top:3px;color:var(--mint);}
 #ciclo-dental .b-paper .rows .k,#ciclo-dental .b-white .rows .k{color:var(--navy);}
 #ciclo-dental .rows .v{font-size:16.5px;line-height:1.85;color:rgba(255,255,255,.75);}
 #ciclo-dental .b-paper .rows .v,#ciclo-dental .b-white .rows .v{color:var(--sub);}
 #ciclo-dental .rows .v b{color:#fff;font-weight:800;}
 #ciclo-dental .b-paper .rows .v b,#ciclo-dental .b-white .rows .v b{color:var(--ink);}

 #ciclo-dental /* ══════ 메이커 ══════ */
 .mk{text-align:left;}
 #ciclo-dental .mk .hd{display:flex;align-items:center;gap:15px;margin-bottom:34px;}
 #ciclo-dental .mk .hd .av{width:54px;height:54px;border-radius:50%;background:var(--navy2);color:#fff;
 display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:800;letter-spacing:.04em;}
 #ciclo-dental .mk .hd .r{font-size:11.5px;font-weight:800;color:var(--navy2);letter-spacing:.12em;margin-bottom:5px;}
 #ciclo-dental .mk .hd .n{font-size:18px;font-weight:800;letter-spacing:-.02em;}
 #ciclo-dental .mk p{font-size:18px;line-height:2.05;color:#3d3b36;}
 #ciclo-dental .mk p+p{margin-top:22px;}
 #ciclo-dental .mk p b{font-weight:800;color:var(--ink);}
 #ciclo-dental .mk .qt{margin:36px 0;padding:30px 32px;background:var(--dark);border-radius:14px;
 font-size:23px;line-height:1.7;font-weight:700;letter-spacing:-.028em;color:#fff;}
 #ciclo-dental .mk .qt .mint-t{color:var(--mint);}
 #ciclo-dental .mk .sn{margin-top:36px;padding-top:22px;border-top:1px solid var(--line);
 font-size:14.5px;color:var(--gray);line-height:1.8;}
 #ciclo-dental .mk .sn b{color:var(--ink);font-weight:800;}

 #ciclo-dental /* ══════ 칼럼 목록 ══════ */
 .cl{margin-top:38px;text-align:left;border-top:1px solid var(--line);}
 #ciclo-dental .cl li{list-style:none;padding:15px 0;border-bottom:1px solid var(--line);
 display:flex;gap:14px;align-items:baseline;}
 #ciclo-dental .cl li .n{font-size:11px;font-weight:800;color:var(--gray);flex:0 0 22px;}
