 #ciclo-dental /* ═══════════ 모션 ═══════════ */
 .rv-up{opacity:0;transform:translateY(44px);
 transition:opacity .8s cubic-bezier(.16,1,.3,1),transform .8s cubic-bezier(.16,1,.3,1);}
 #ciclo-dental .rv-up.on{opacity:1;transform:none;}

 #ciclo-dental .rv-sc{opacity:0;transform:scale(.88) translateY(24px);
 transition:opacity .75s cubic-bezier(.16,1,.3,1),transform .75s cubic-bezier(.16,1,.3,1);}
 #ciclo-dental .rv-sc.on{opacity:1;transform:none;}

 #ciclo-dental /* 거대 숫자: 아래에서 솟아오르며 확대 */
 .rv-pop{opacity:0;transform:scale(.55) translateY(60px);filter:blur(12px);
 transition:opacity 1s cubic-bezier(.2,1.2,.32,1),
 transform 1s cubic-bezier(.2,1.2,.32,1),
 filter .8s ease;}
 #ciclo-dental .rv-pop.on{opacity:1;transform:none;filter:blur(0);}

 #ciclo-dental /* 스냅 장면 전용: 진입 시 배경도 살짝 확대 */
 .scr.snap > *{will-change:transform,opacity;}

 #ciclo-dental /* 헤드라인: 글자가 아래에서 밀려 올라옴 (마스크) */
 .rv-mask{overflow:hidden;display:block;}
 #ciclo-dental .rv-mask > span{display:block;transform:translateY(105%);
 transition:transform .95s cubic-bezier(.16,1,.3,1);}
 #ciclo-dental .rv-mask.on > span{transform:none;}

 #ciclo-dental /* 좌우 슬라이드 */
 .rv-l{opacity:0;transform:translateX(-46px);
 transition:opacity .8s cubic-bezier(.16,1,.3,1),transform .8s cubic-bezier(.16,1,.3,1);}
 #ciclo-dental .rv-l.on{opacity:1;transform:none;}
 #ciclo-dental .rv-r{opacity:0;transform:translateX(46px);
 transition:opacity .8s cubic-bezier(.16,1,.3,1),transform .8s cubic-bezier(.16,1,.3,1);}
 #ciclo-dental .rv-r.on{opacity:1;transform:none;}

 #ciclo-dental /* 순차 지연 */
 .dl1{transition-delay:.1s}#ciclo-dental .dl2{transition-delay:.2s}#ciclo-dental .dl3{transition-delay:.3s}
 #ciclo-dental .dl4{transition-delay:.4s}#ciclo-dental .dl5{transition-delay:.5s}#ciclo-dental .dl6{transition-delay:.6s}
 #ciclo-dental .dl7{transition-delay:.75s}#ciclo-dental .dl8{transition-delay:.95s}

 #ciclo-dental /* 검색결과 행 순차 — 빠르게 우수수 */
 .serp .rw{opacity:0;transform:translateX(-10px);
 transition:opacity .34s ease,transform .34s ease;}
 #ciclo-dental .serp.on .rw{opacity:1;transform:none;}
