 #ciclo-dental .serp.on .rw:nth-of-type(3){transition-delay:.1s}
 #ciclo-dental .serp.on .rw:nth-of-type(4){transition-delay:.15s}
 #ciclo-dental .serp.on .rw:nth-of-type(5){transition-delay:.2s}
 #ciclo-dental .serp.on .rw:nth-of-type(6){transition-delay:.25s}
 #ciclo-dental .serp.on .rw:nth-of-type(7){transition-delay:.3s}
 #ciclo-dental .serp.on .rw:nth-of-type(8){transition-delay:.35s}
 #ciclo-dental .serp.on .rw:nth-of-type(9){transition-delay:.4s}
 #ciclo-dental .serp.on .rw:nth-of-type(10){transition-delay:.45s}
 #ciclo-dental .serp.on .rw:nth-of-type(11){transition-delay:.5s}
 #ciclo-dental .serp.on .rw:nth-of-type(12){transition-delay:.55s}
 #ciclo-dental .serp.on .rw:nth-of-type(13){transition-delay:.6s}
 #ciclo-dental .serp.on .rw:nth-of-type(14){transition-delay:.65s}
 #ciclo-dental .serp.on .rw:nth-of-type(15){transition-delay:.7s}
 #ciclo-dental .serp.on .rw:nth-of-type(16){transition-delay:.75s}
 #ciclo-dental .serp.on .rw:nth-of-type(17){transition-delay:.8s}
 #ciclo-dental .serp.on .rw:nth-of-type(18){transition-delay:.85s}
 #ciclo-dental .serp.on .rw:nth-of-type(19){transition-delay:.9s}
 #ciclo-dental /* 마지막 노란 줄: 자동 스크롤이 바닥에 닿을 때 등장 */
 .serp .rw.me{opacity:0;transform:translateY(14px);}
 #ciclo-dental .serp.on .rw.me{
 opacity:1;transform:none;
 transition:opacity .6s ease 3.1s,transform .6s ease 3.1s;
 }
 #ciclo-dental .serp .dots,#ciclo-dental .serp .scroll-note{opacity:0;transition:opacity .35s ease;}
