 #ciclo-dental .serp.on .scroll-note{opacity:1;transition-delay:1.1s;}

 #ciclo-dental /* 게이지 채우기 */
 .tk i{width:0;transition:width 1.5s cubic-bezier(.22,1,.36,1) .2s;}
 #ciclo-dental .tk.on i{width:70%;}
