 #ciclo-dental .rc .st .bar.on i{width:var(--w) !important;}

 #ciclo-dental /* 숫자 카운트업 자리 고정 */
 .cnt{font-variant-numeric:tabular-nums;}

 /* 화살표 통통 */
 @keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(9px)}}
 #ciclo-dental .chev{animation:bob 1.9s ease-in-out infinite;}

 #ciclo-dental /* 하이라이트 박스: 왼→오른쪽으로 칠해짐 */
 .box{position:relative;}
 #ciclo-dental .swipe{
 display:inline-block;position:relative;color:transparent !important;
 }
 #ciclo-dental .swipe::before{
 content:attr(data-t);position:absolute;inset:0;
 display:flex;align-items:center;justify-content:center;
 color:var(--navy);z-index:2;white-space:nowrap;
 }
 #ciclo-dental .swipe::after{
 content:"";position:absolute;inset:0;background:var(--yellow);
 border-radius:8px;transform:scaleX(0);transform-origin:left;
 transition:transform .7s cubic-bezier(.76,0,.24,1) .1s;z-index:1;
 }
 #ciclo-dental .swipe.on::after{transform:scaleX(1);}

 /* 게이지 펄스 */
 @keyframes pulse{
 0%,100%{box-shadow:0 0 0 0 rgba(232,69,60,.5)}
 50%{box-shadow:0 0 0 7px rgba(232,69,60,0)}
 }
 #ciclo-dental .pip{animation:pulse 1.8s ease-out infinite;}

 /* 견적서 흔들림 강조 */
 @keyframes shake{
 0%,100%{transform:rotate(-1.4deg)}
 22%{transform:rotate(-2.6deg) translateX(-4px)}
 44%{transform:rotate(-.2deg) translateX(4px)}
 66%{transform:rotate(-2deg) translateX(-2px)}
 }
 #ciclo-dental .quote.on{animation:shake .62s ease-in-out .55s;}

 /* 노란 줄 강조 깜빡 */
 @keyframes flash{
 0%,100%{background:var(--yellow)}
 50%{background:#fff3a8}
 }
 #ciclo-dental .serp.on .rw.me{animation:flash .7s ease-in-out 3.8s 2;}

 /* 배경 원 천천히 회전 */
 @keyframes spin{to{transform:rotate(360deg)}}
 #ciclo-dental .orb{
 position:absolute;border-radius:50%;pointer-events:none;
 border:1px dashed rgba(255,212,0,.22);
 animation:spin 46s linear infinite;
 }

 #ciclo-dental /* 형광펜 긋기 — 노란 띠 위에 글자를 얹음 */
 .pen{
 position:relative;display:inline-block;padding:2px 12px;isolation:isolate;
 }
 #ciclo-dental .pen::before{
 content:"";position:absolute;left:0;right:0;top:0;bottom:0;
 background:var(--yellow);border-radius:4px;
 transform:scaleX(0);transform-origin:left center;
 transition:transform .8s cubic-bezier(.22,1,.36,1) .2s;
 z-index:1;
 }
 #ciclo-dental .pen > span{position:relative;z-index:2;}
 #ciclo-dental .pen.on::before{transform:scaleX(1);}

 /* 접근성 */
 @media (prefers-reduced-motion:reduce){
 #ciclo-dental{scroll-snap-type:none;scroll-behavior:auto;}
 #ciclo-dental .scr.snap{min-height:0;padding:110px var(--P);}
 #ciclo-dental .rv-up,#ciclo-dental .rv-sc,#ciclo-dental .rv-pop,#ciclo-dental .rv-l,#ciclo-dental .rv-r,#ciclo-dental .serp .rw,#ciclo-dental .serp .dots,#ciclo-dental .serp .scroll-note,#ciclo-dental .tk i,#ciclo-dental .rc .st .bar i,#ciclo-dental .pen,#ciclo-dental .pen::before,#ciclo-dental .swipe::after{
 transition:none !important;opacity:1 !important;transform:none !important;filter:none !important;
 }
 #ciclo-dental .tk i{width:70% !important;}
 #ciclo-dental .pen::before{transform:scaleX(1) !important;}
 #ciclo-dental .swipe::after{transform:scaleX(1) !important;}
 #ciclo-dental .chev,#ciclo-dental .orb,#ciclo-dental .pip,#ciclo-dental .quote.on,#ciclo-dental .serp.on .rw.me{animation:none !important;}
 }

 #ciclo-dental /* ══════ 브랜드 마크 ══════ */
 .brandmark{display:flex;flex-direction:column;align-items:center;}
 #ciclo-dental .brandmark svg{width:112px;height:112px;}
 #ciclo-dental .brandmark .bn{
 font-size:44px;font-weight:800;letter-spacing:.22em;color:#fff;
 margin-top:26px;padding-left:.22em;
 }
 #ciclo-dental .brandmark .bt{
