<script>

(function(){
 var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

 // ── 등장 대상 자동 지정 ──────────────────────────
 document.querySelectorAll('.scr').forEach(function(sec){
 var kids = sec.children;
 var i = 0;
 for (var k = 0; k < kids.length; k++){
 var el = kids[k];
 if (el.classList.contains('serp') || el.classList.contains('quote') || el.classList.contains('ai')){
 el.classList.add('rv-sc');
 } else if (el.classList.contains('xxl')){
 el.classList.add('rv-pop'); // 거대 숫자는 솟아오름
 } else if (el.classList.contains('xl') || el.classList.contains('lg')){
 el.classList.add('rv-up');
 } else {
 el.classList.add('rv-up');
 }
 i++;
 if (i <= 8) el.classList.add('dl' + Math.min(i,8));
 }
 });

 // 리스트 내부 항목도 순차 등장
 document.querySelectorAll('.rows .r, .rw .rc, .tl .e, .fq .i, .wk .c, .rv .v, .cl li')
 .forEach(function(el, n){
 el.classList.add('rv-up');
 el.classList.add('dl' + ((n % 6) + 1));
 });

 // 2갈래 카드는 좌우에서 슬라이드
 document.querySelectorAll('.duo').forEach(function(d){
 var c = d.children;
 if (c[0]) c[0].classList.add('rv-l','dl1');
 if (c[1]) c[1].classList.add('rv-r','dl3');
 });

 // 비교표 행 순차
 document.querySelectorAll('.vs tbody tr').forEach(function(tr, n){
 tr.classList.add('rv-l');
 tr.classList.add('dl' + ((n % 6) + 1));
 });

 if (reduce){
 document.querySelectorAll('.rv-up,.rv-sc,.rv-pop,.rv-l,.rv-r,.rv-mask,.pen,.swipe')
 .forEach(function(e){ e.classList.add('on'); });
 document.querySelectorAll('.tk,.serp').forEach(function(e){ e.classList.add('on'); });
 return;
 }

 // ── 스크롤 진입 감지 ────────────────────────────
 var SEL = '.rv-up,.rv-sc,.rv-pop,.rv-l,.rv-r,.rv-mask,.serp,.tk,.pen,.swipe,.quote,.rc .st .bar';

 var io = new IntersectionObserver(function(entries){
 entries.forEach(function(en){
 if (!en.isIntersecting) return;
 en.target.classList.add('on');
 io.unobserve(en.target);
 });
 }, { threshold: 0, rootMargin: '0px 0px -12% 0px' }); // inline 요소도 잡히게 threshold 0

 document.querySelectorAll(SEL).forEach(function(el){ io.observe(el); });

 // 재고 게이지 폭을 CSS 변수로 이전
 document.querySelectorAll('.rc .st .bar i').forEach(function(i){
 var w = i.style.width;
 i.parentElement.style.setProperty('--w', w);
 i.style.width = '0';
 });

 // 검색결과 박스: 등장 후 노란 줄까지 자동 스크롤 (한참 내려가는 연출)
 var serpIO = new IntersectionObserver(function(es){
 es.forEach(function(e){
 if (!e.isIntersecting) return;
 var box = e.target;
 serpIO.unobserve(box);
 setTimeout(function(){
 var me = box.querySelector('.rw.me');
 if (!me) return;
 var start = box.scrollTop;
 var end = box.scrollHeight - box.clientHeight;
 var t0 = null, dur = 2600;
 function step(ts){
 if (!t0) t0 = ts;
 var p = Math.min((ts - t0) / dur, 1);
 var e2 = p < .5 ? 2*p*p : 1 - Math.pow(-2*p + 2, 2) / 2;
 box.scrollTop = start + (end - start) * e2;
 if (p < 1) requestAnimationFrame(step);
 }
 requestAnimationFrame(step);
 }, 900);
 });
 }, { threshold: .35 });
 document.querySelectorAll('.serp').forEach(function(b){ serpIO.observe(b); });

 // 첫 화면은 스크롤 없이 보이므로 즉시 실행
 window.addEventListener('load', function(){
 setTimeout(function(){
 document.querySelectorAll(SEL).forEach(function(el){
 var r = el.getBoundingClientRect();
 if (r.top < window.innerHeight * 0.92 && r.bottom > 0){
 el.classList.add('on');
 io.unobserve(el);
 }
 });
 }, 200);
 });
})();

</script>"}}],"isInner":false}]
